        id: "cgei-ds-probability-dependence-equation-1",
        kind: "equation",
        title: "Bayes’ rule",
        expression: "P(A\\mid B) = \\frac{P(B\\mid A)\\,P(A)}{P(B)}",
        body: "Symbols: A: Event of interest; B: Evidence",
